cat > sha256_rule.yara << 'EOF'
rule SHA256Match {
  condition:
    hash.sha256(0, filesize) == "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
}
EOF

cat > callable.yara << 'EOF'
rule Callable {
  condition:
    filesize > 1000000 and uint32(0) == 0x5A4D
}
EOF

cat > reflection.yara << 'EOF'
rule ReflectionInjection {
  strings:
    $ref1 = "LoadLibrary"
    $ref2 = "GetProcAddress"
    $ref3 = { FF D? }
  condition:
    2 of them
}
EOF

cat > resource.yara << 'EOF'
import "pe"
rule ResourceDetect {
  condition:
    for any resource in pe.resources : ( resource.name == "TYPELIB" )
}
EOF

cat > section_entropy.yara << 'EOF'
import "pe"
import "math"
rule SectionEntropy {
  condition:
    for any section in pe.sections : ( math.entropy(section.raw_data_offset, section.raw_data_size) > 7.0 )
}
EOF

cat > hollow.yara << 'EOF'
rule ProcessHollowing {
  strings:
    $s1 = "NtUnmapViewOfSection"
    $s2 = "NtCreateProcess"
    $s3 = { 48 8B C4 48 89 58 08 }
  condition:
    2 of them
}
EOF
